		{
			text = [=[Em Pesadelos, o fragmento levado a {link:darnassus}Darnassus{/link}]=],
		},
	},
	bonds = {
		{ id = "disciple-of-naralex", name = "Discípulo de Naralex", note = "seu aluno fiel" },
		{ id = "lord-serpentis", name = "Lorde Serpentis", note = "seu aluno, agora seu carcereiro" },
		{ id = "mutanus-the-devourer", name = "Mutanus, o Devorador", note = "o pesadelo que guarda seu sono" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "leu o fragmento de seu pesadelo" },
	},
})

Translate("ptBR", "disciple-of-naralex", {
	title = "Discípulo de Naralex",
	subtitle = "O Último Discípulo Fiel",
	found = "A entrada da Caverna Ululante",
