	allegiance = "Discípulos de Naralex · Tauren",
	sections = {
		{
			title = "Resumo",
			text = [=[O Discípulo de Naralex é um druida {link:tauren}tauren{/link}, um dos poucos seguidores de {link:naralex}Naralex{/link} que o pesadelo não deformou. Ele espera logo na entrada da {link:wailing-caverns}Caverna Ululante{/link}. Seu mestre voltou a dormir, diz ele, e feras reptilianas vazam de seus sonhos para a terra. Naralex precisa ser despertado de seu pesadelo ou estará perdido para sempre, e um grande mal será libertado. Mas o Discípulo não pode realizar o rito do despertar enquanto seus irmãos corrompidos viverem. Os quatro {link:druids-of-the-fang}Senhores da Presa{/link} precisam morrer primeiro.]=],
		},
		{
			title = "Importância",
			text = [=[O Discípulo é a única esperança do sonhador. Ele conhece o rito que pode trazer {link:naralex}Naralex{/link} de volta, e manteve a fé apesar de tudo o que a caverna se tornou. Fala dela com tristeza: antes um templo de promessa para os {link:the-barrens}Sertões{/link}, agora salões de pesadelo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Abençoa com a marca do selvagem os que desejam entrar na caverna.
• Pede a morte dos quatro {link:druids-of-the-fang}Senhores da Presa{/link}.
• Bane os espíritos dos Senhores da Presa mortos dentro de um círculo de fogo.
• Alcança o {link:emerald-dream}Sonho Esmeralda{/link} para despertar seu mestre.]=],
		},
	},
	chapters = {
		{
			title = "O Rito do Despertar",
			hint = [=[Mate os Senhores da Presa e depois proteja o Discípulo no caminho até Naralex.]=],
			text = [=[Quando os {link:druids-of-the-fang}Senhores da Presa{/link} morreram, o Discípulo declarou que nem toda esperança estava perdida, mas ele não poderia concluir o rito sozinho. Abriu caminho pela caverna, purificando-a enquanto avançava, enquanto os pesadelos de seu mestre enviavam víboras e coisas piores contra ele. Ao lado de {link:naralex}Naralex{/link}, mergulhou no Sonho. O ritual foi longo, e os ataques ficaram mais ferozes, até que por fim o sonhador despertou.]=],
		},
	},
	mentions = {
		{
			text = [=[Couros Aberrantes, pedida por seu companheiro de discipulado Nalpak]=],
		},
		{
			text = [=[Erradicação Aberrante, pedida por seu companheiro de discipulado Ebru]=],
		},
	},
	bonds = {
		{ id = "naralex", name = "Naralex", note = "seu mestre" },
		{ id = "lord-serpentis", name = "Lorde Serpentis", note = "um irmão que caiu" },
	},
})

