	sections = {
		{
			title = "Resumo",
			text = [=[Kresh é uma tartaruga ancestral que nada no rio subterrâneo da {link:wailing-caverns}Caverna Ululante{/link}. Estranhamente, o pesadelo não a tocou. Enquanto tudo à sua volta se deforma e adoece, ela continua a viver como sempre viveu, plácida e alheia ao mal na escuridão. Muitos tentaram tomar seu grande casco. Ela o conservou.]=],
