		{
			title = "Importância",
			text = [=[Kresh é a única criatura da caverna que o pesadelo não conseguiu mudar.]=],
		},
		{ title = "Feitos", text = "• Vagueia pelo rio, intocada pela corrupção." },
	},
})

Translate("ptBR", "druids-of-the-fang", {
	title = "Druids of the Fang",
	aliases = { "Druid of the Fang", "Senhores da Presa", "Senhor da Presa" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Druids of the Fang são os seguidores corrompidos de {link:naralex}Naralex{/link}. Vieram à {link:wailing-caverns}Caverna Ululante{/link} como uma ordem de druidas nobres, com a intenção de curar os {link:the-barrens}Sertões{/link}. Quando o sonho de seu mestre virou pesadelo, a maioria caiu com ele. Agora usam rostos escamosos e formas de serpente, e buscam refazer a terra à imagem de seus próprios sonhos distorcidos.]=],
		},
		{
			title = "A Ordem",
			text = [=[Quatro líderes os comandam, os Senhores da Presa: {link:lady-anacondra}Lady Anacondra{/link}, {link:lord-cobrahn}Lorde Cobrahn{/link}, {link:lord-pythas}Lorde Pythas{/link} e o chefe deles, {link:lord-serpentis}Lorde Serpentis{/link}. Cada um guarda uma gema do sonho. Abaixo deles, druidas da Presa mantêm serpentes e raptores aberrantes como suas feras, e alguns andam pelas planícies lá em cima. Um deles, Boahn, foi visto perto do morro da caverna. Os poucos discípulos que mantiveram o juízo, entre eles Nalpak, Ebru e o Discípulo que espera lá dentro, agora trabalham contra seus irmãos caídos.]=],
		},
		{
			title = "O que os Druidas Viram",
			text = [=[{link:hamuul-runetotem}Hamuul Runetotem{/link} entrou no sonho para descobrir o que envenenava os {link:the-barrens}Sertões{/link}. Viu um culto de druidas cujos objetivos um dia foram nobres e que haviam perdido o rumo, servindo à mácula que se infiltrava pela terra. Ele era velho e não pôde ficar muito tempo. {link:nara-wildmane}Nara Wildmane{/link} ficou, e viu seus rostos. Ela diz que eles ainda a assombram.]=],
		},
	},
})
